for(const l of lessons)for(const e of l.examples)readingLexicon[e.th]=e.ro;
readingLexicon['ช้า ๆ']='cháa cháa';
const readingKeys=Object.keys(readingLexicon).sort((a,b)=>b.length-a.length);
function romanizeThai(text){if(readingLexicon[text])return readingLexicon[text];let i=0,out=[];while(i<text.length){if(/\s/.test(text[i])){i++;continue}const k=readingKeys.find(k=>text.startsWith(k,i));if(k){out.push(readingLexicon[k]);i+=k.length}else{out.push('□');i++}}return out.filter(Boolean).join(' ')}
function readingMarkup(th){return `<span class="thai-reading"><span lang="th">${esc(th)}</span><span class="inline-ro" lang="th-Latn">${esc(romanizeThai(th))}</span></span>`}
function annotateReadings(root){const walker=document.createTreeWalker(root,NodeFilter.SHOW_TEXT),nodes=[];while(walker.nextNode()){const n=walker.currentNode;if(/[\u0e00-\u0e7f]/.test(n.textContent)&&!n.parentElement.closest('.x-lesson-row,.thai-reading,.th,.ro,.anatomy-th,.anatomy-ro,.word-main,.word-ro,.word-th,.thai-art,script,style,select,option,[aria-hidden="true"]'))nodes.push(n)}for(const n of nodes){const text=n.textContent,frag=document.createDocumentFragment();let end=0;for(const m of text.matchAll(/[\u0e00-\u0e7f]+(?:[ \u00a0]+[\u0e00-\u0e7f]+)*/g)){frag.append(text.slice(end,m.index));const el=document.createElement('span');el.innerHTML=readingMarkup(m[0]);frag.append(el.firstChild);end=m.index+m[0].length}frag.append(text.slice(end));n.replaceWith(frag)}}
